const r=$json||{};
let text=String(r.output_text||'').trim();
if(!text&&Array.isArray(r.output)){
  for(const item of r.output||[]){
    for(const part of item?.content||[]){
      if(part?.type==='output_text'&&part?.text)text+=String(part.text);
    }
  }
}
text=text.trim();
if(!text)throw new Error('OpenAI не вернул текст');
const expanded=(text.match(/РАСШИРЕННАЯ\s+ГИПОТЕЗА\s*:\s*([\s\S]*?)(?=\n\s*КОРОТКАЯ\s+ГИПОТЕЗА\s*:|$)/i)?.[1]||'').trim();
const short=(text.match(/КОРОТКАЯ\s+ГИПОТЕЗА\s*:\s*([\s\S]*?)$/i)?.[1]||'').trim();
return [{json:{reply:text,expandedHypothesis:expanded,shortHypothesis:short}}];
